def are_balanced(parentheses: str) -> bool:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    determine if all the parenthesis are balanced.
    Return True if parenthesis are balanced. Otherwise, return False.
    >>> are_balanced('( ) (( )) (( )( ))')
    True
    >>> are_balanced('())')
    False
    """
    balanced = True
    stack = []
    for char in parentheses:
        if char in '()':
            if char == '(':
                stack.append(char)
            else:
                if not stack:
                    balanced = False
                    break
                stack.pop()
    if stack:
        balanced = False
    return balanced


