def is_valid_ip(ip: str) -> bool:
    """ Given a string representing a number, return True if the string represents a valid IPv4 address, and False if it
    does not.
    >>> is_valid_ip('1.2.3.4')
    True
    >>> is_valid_ip('256.1.2.3')
    False
    """
    try:
        parts = ip.split('.')
        if len(parts) != 4:
            return False
        for part in parts:
            if not part.isdigit():
                return False
            if int(part) < 0 or int(part) > 255:
                return False
        return True
    except ValueError:
        return False


