def binary_tree(root, left, right):
    return [root, left, right]


def root(tree):
    return tree[0]


def left(tree):
    return tree[1]


def right(tree):
    return tree[2]


def is_empty_binary_tree(tree):
    return tree == []


def size(tree):
    if is_empty_binary_tree(tree):
        return 0
    else:
        return 1 + size(left(tree)) + size(right(tree))


def num_leaves(tree):
    """ Return number of leaves in given tree """
    if is_empty_binary_tree(tree):
        return 0
    elif is_empty_binary_tree(left(tree)) and is_empty_binary_tree(right(tree)):
        return 1
    else:
        return num_leaves(left(tree)) + num_leaves(right(tree))


def preorder(tree):
    """ Return the preorder traversal of a binary tree tree """
    if is_empty_binary_tree(tree):
        return []
    else:
        return [root(tree)] + preorder(left(tree)) + preorder(right(tree))


def inorder(tree):
    """ Return the inorder traversal of a binary tree tree """
    if is_empty_binary_tree(tree):
        return []
    else:
        return inorder(left(tree)) + [root(tree)] + inorder(right(tree))


def postorder(tree):
    """ Return the postorder traversal of a binary tree tree """
    if is_empty_binary_tree(tree):
        return []
    else:
        return postorder(left(tree)) + postorder(right(tree)) + [root(tree)]


def tree_elem_index(tree, element):
    """ Return index of element in a sorted array of binary tree"""
    if is_empty_binary_tree(tree):
        return -1
    elif root(tree) == element:
        return 0
    elif element < root(tree):
        left_index = tree_elem_index(left(tree), element)
        if left_index == -1:
            return -1
        else:
            return 1 + left_index
    elif element > root(tree):
        right_index = tree_elem_index(right(tree), element)
        if right_index == -1:
            return -1
        else:
            return 1 + size(left(tree)) + right_index
    else:
        return -1


def tree_elem(tree, index):
    """ Return element at index in sorted binary tree tree """
    if is_empty_binary_tree(tree):
        return None
    elif index == 0:
        return root(tree)
    elif index < size(left(tree)):
        return tree_elem(left(tree), index)
    elif index > size(left(tree)):
        return tree_elem(right(tree), index - size(left(tree)) - 1)
    else:
        return None


def tree_map(tree, f):
    """ Return the tree whose node values are the values
    of tree after apply f to every node value
    """
    if is_empty_binary_tree(tree):
        return []
    else:
        return [f(root(tree))] + tree_map(left(tree), f) + tree_map(right(tree), f)


def tree_filter(tree, pred):
    """ Return tree after keep elements which satisfy the pred
    (if pred returns True) in given tree
    """
    if is_empty_binary_tree(tree):
        return []
    elif pred(root(tree)):
        return [root(tree)] + tree_filter(left(tree), pred) + tree_filter(right(tree), pred)
    else:
        return tree_filter(left(tree), pred) + tree_filter(right(tree), pred)


def tree_largest_smaller(tree, val):
    """ Return the largest value in tree that is smaller than val """
    if is_empty_binary_tree(tree):
        return None
    elif val < root(tree):
        return tree_largest_smaller(left(tree), val)
    elif val > root(tree):
        if tree_largest_smaller(right(tree), val) == None:
            return root(tree)
        else:
            return tree_largest_smaller(right(tree), val)
    else:
        return None


def tree_smallest_larger(tree, val):
    """ Return the smallest value in tree that is larger than val """
    if is_empty_binary_tree(tree):
        return None
    elif val > root(tree):
        return tree_smallest_larger(right(tree), val)
    elif val < root(tree):
        if tree_smallest_larger(left(tree), val) == None:
            return root(tree)
        else:
            return tree_smallest_larger(left(tree), val)
    else:
        return None


def tree_remove(tree, val):
    """ Return the tree after removing the val in tree """
