def is_subsequence(string1: str, string2: str) -> bool:
    """ Returns whether string1 is a subsequence of string2.
    >>> is_subsequence('abc', 'ahbgdc')
    True
    >>> is_subsequence('axc', 'ahbgdc')
    False
    """
    i, j = 0, 0
    while i < len(string1) and j < len(string2):
        if string1[i] == string2[j]:
            i += 1
        j += 1
    return i == len(string1)


def is_subsequence_recursive(string1: str, string2: str) -> bool:
    """ Returns whether string1 is a subsequence of string2.
    >>> is_subsequence_recursive('abc', 'ahbgdc')
    True
    >>> is_subsequence_recursive('axc', 'ahbgdc')
    False
    """
    if not string1:
        return True
    if not string2:
        return False
    if string1[0] == string2[0]:
        return is_subsequence_recursive(string1[1:], string2[1:])
    else:
        return is_subsequence_recursive(string1, string2[1:])


