def hamming_distance(a, b):
    """
    Takes two bytes and returns their hamming distance
    """
    xor = xor_bytes(a, b)
    return sum((bin(x)[2:].count("1") for x in xor))


def optimal_shift(string):
    """
    takes a bytes object and returns the optimal shift value for a caesar cipher for that string
    """
    dists = [0] * 26
    for shift in range(26):
        for letter in string:
            dists[shift] += 1 if (ord(letter) - shift > 64) else 0
        dists[shift] /= len(string)
    return dists.index(max(dists))


def shift_by(string, shift):
    """
    Takes bytes and return bytes of a caesar cipher by shift value
    """
    shifted = b''
    for char in string:
        shifted += bytes([(char - shift) % 26 + 65])
    return shifted


def caesar_break(encrypted):
    """
    Take bytes object and returns the encrypted string by caesar cipher
    """
    dists = [hamming_distance(encrypted, shift_by(encrypted, i)) for i in range(26)]
    return chr(dists.index(min(dists)) + 65)


def decode_base64(string):
    """
    Takes string encoded by base64 and returns its original string.
    Note: We can use builtin base64.decode but I think it doesn't get to the base concept
    of Base64 algorithm
    """
    encoded_chars = [str(int(i, 2)) for i in re.findall(r"........", string)]
    decoded_chars = []
    for i in range((len(encoded_chars) + 1) // 4):
        char = 0
        for j in range(4):
            char += int(encoded_chars[4 * i + j]) * (2 ** (3 - j))
        if char < 64:
            decoded_chars.append(char)
    return bytes(chr(char) for char in decoded_chars).decode()


