"""
Find the middle node of a linked list.
"""


class ListNode:
    def __init__(self, x):
        self.val = x
        self.next = None


class Solution:
    def middleNode(self, head: ListNode):
        """
        One pointer goes through the list, while the second pointer goes through the list every other node.
        When the fast pointer reaches the end, the slow pointer will be in the middle.
        """
        slow, fast = head, head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
        return slow
