def circular_string(s: str):
    """
    Given a circular string (which is a string that wraps around at the end, like a
    circle), output the longest substring of unique characters.
    """
    if len(s) <= 1:
        return s
    i, j = 0, 1
    res = s[i]
    while j < len(s):
        if s[j] in res:
            i += res.index(s[j]) + 1
        else:
            res += s[j]
        j += 1
    return res


