def binomial_coeffs(n: int, k: int):
    """
    This function calculates the binomial coefficient using Pascal's triangle.
    """
    dp = [[0 for _ in range(n + 1)] for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = dp[i][i] = 1
        for j in range(1, i):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
    return dp[n][k]


