def shortest_path(maze: List[List[str]]) -> List[Tuple[int, int]]:
    """This function will find the shortest path through a maze.  The maze is represented as a list of lists
    where each element in the list is either 'U', 'D', 'L', 'R' to represent a UP, DOWN, LEFT, and RIGHT
    movement, or '*' to represent an obstacle.  The function will return a list of tuples representing the
    shortest path through the maze.  If there is no path, the function will return None.
    >>> shortest_path([['*', 'L', 'R'], ['U', 'R', '*'], ['D', 'L', 'R']])
    [(0, 0), (1, 1), (2, 2)]
    >>> shortest_path([['*', 'L', 'R'], ['U', 'R', '*'], ['D', 'L', 'R']])
    None
    >>> shortest_path([['U', 'R', 'D'], ['L', 'R', 'L'], ['R', 'D', 'R']])
    [(0, 0), (1, 1), (2, 2)]
    >>> shortest_path([['U', 'R', 'D'], ['L', 'R', 'L'], ['R', 'D', 'R']])
    [(0, 0), (1, 1), (2, 2)]
    >>> shortest_path([['U', 'R', 'D'], ['L', 'R', 'L'], ['R', 'D', 'R']])
    [(0, 0), (1, 1), (2, 2)]
    """
    def shortest_path_helper(maze: List[List[str]], row: int, col: int, path: List[Tuple[int, int]], visited: Set[Tuple[int, int]]) -> List[Tuple[int, int]]:
        if (row, col) in visited or row < 0 or col < 0 or row >= len(maze) or col >= len(maze[0]) or maze[row][col] == '*':
            return path
        path.append((row, col))
        visited.add((row, col))
        if row == len(maze) - 1 and col == len(maze[0]) - 1:
            return path
        if maze[row][col] == 'U':
            return shortest_path_helper(maze, row-1, col, path, visited)
        if maze[row][col] == 'D':
            return shortest_path_helper(maze, row+1, col, path, visited)
        if maze[row][col] == 'L':
            return shortest_path_helper(maze, row, col-1, path, visited)
        if maze[row][col] == 'R':
            return shortest_path_helper(maze, row, col+1, path, visited)
        return shortest_path_helper(maze, row-1, col, path, visited) or shortest_path_helper(maze, row+1, col, path, visited) or shortest_path_helper(maze, row, col-1, path, visited) or shortest_path_helper(maze, row, col+1, path, visited)
    return shortest_path_helper(maze, 0, 0, [], set())

