    """
    Checks if given words differ only by one letter
    >>> one_letter_diff('pet', 'pit')
    True
    >>> one_letter_diff('apple', 'apple')
    False
    >>> one_letter_diff('apple', 'appleseed')
    False
    >>> one_letter_diff('apple', 'applz')
    True
    """
    count = 0
