    """
    Finds the shortest ladder of words that changes one letter at a time
    to change begin to end, at each step checking
    if the word is in the word list
    """
    if begin == end:
        return []
    options = set()
    for word in words:
        if one_letter_diff(begin, word):
            options.add(word)
    for word in options:
