def find_word_ladders_rec(begin: str, end: str, ladder: list, words: set):
    """
    Finds all the word ladders from begin to end
    using the words in the set
    """
    if begin == end:
        yield ladder
    for word in [begin]:
        if not one_letter_diff(word, begin):
            return []
    for word in words:
        if one_letter_diff(begin, word):
            for ladder2 in find_word_ladders_rec(word, end, ladder + [word], words):
                yield ladder2
    return []


