    for i in range(2, n):
        if n % i == 0:
            return 0
    return 1


def fermat(n: int):
    """Return 1 if n is a prime and 0 if it is not, using Fermat little theorem (be careful with small primes)."""
    if is_prime(n):
        return 1
    else:
        return 0


def miller_rabin(n: int, rounds: int = 50):
    """Return 1 if n is a prime and 0 if it is not (via Miller-Rabin probabilistic primality test)."""
    if is_prime(n):
        return 1
    else:
        for _ in range(rounds):
            a = random.randint(2, n - 2)
            if pow(a, n - 1, n) != 1:
                return 0
        return 1


def pollard(n: int):
    """Return 1 if n is a prime and 0 if it is not (via Pollard p-1).
    Be aware, that this algorithm is very slow."""
    prime_factors = []
    a = 2
    L = [2]
    while L[-1] < n:
        L.append(L[-1] * a)
    k = 1
    r = L[-1] - 1
    if pow(a, r, n) == 1:
        r = r - 1
    d = gcd(n, L[-1] - 1)
    if d != 1:
        return 0
    else:
        for _ in range(k):
            d = gcd(n, L[-1] - 1)
            if d != 1:
                prime_factors.append(d)
        return 1


def jacobi(a: int, p: int):
    """Return Jacobi symbol a/p. Needs to be positive integers."""
    if p == 1:
        return 1
    if not a % p:
        return 0
    if is_prime(p) and p != 2:
        return pow(a, ((p - 1) / 2), p)
    if not a % 2:
        return pow(1, ((p - 1) / 2), p) * pow(-1, ((a / 2) * ((p - 1) / 2)) / 2)
    else:
        return pow(a, ((p - 1) / 2), p) * pow(-1, (a - 1) / 2)


def jacobi_def(a: int, p: int):
    """Return 1 if Jacobi symbol a/p is 1 and 0 if it is not."""
    if a % p:
        return 1
    else:
        return 0


