def find_frequency(string: str):
    """
    finds the frequency of characters and adds to map. values are sorted
    """
    count_map = dict()
    for ch in string:
        if ch.isalpha():
            ch = ch.upper()
            if ch not in count_map:
                count_map[ch] = 1
            else:
                count_map[ch] += 1

    return {ch: val for ch, val in sorted(count_map.items(), key=lambda item: item[1], reverse=True)}


