def get_key_length(s: str):
    """
    takes as input a single string and returns the key length for the string.
    """
    key_length = [0] * 26
    for i in range(1, 27):
        substrings = [s[j:j + i] for j in range(0, len(s) - i + 1, i)]
        for j in range(len(substrings) - i + 1):
            key_length[i] += hamming_distance(substrings[j], substrings[j + i])
    return key_length.index(min(key_length[1:]))


