def encode_geni(given_code: str, given_value: str):
    """
    takes as input a string of 'encoded' characters. Returns encoded string using given_value.
    """
    code_list = "abcdefghijklmnopqrstuvwxyz"
    out_list = []
    for ch in given_value:
        if ch in code_list:
            out_list.append(str(ord(ch) - ord("a")))
    return given_code.translate(str.maketrans(code_list, "".join(out_list)))


def decode_geni(given_code: str, given_value: str):
    """
    takes as input a string of 'decoded' characters. Returns decoded string using given_value.
    """
    code_list = "abcdefghijklmnopqrstuvwxyz"
    out_list = []
    for ch in given_value:
        if ch in code_list:
            out_list.append(str(ord(ch) - ord("a")))
    return given_code.translate(str.maketrans("".join(out_list), code_list))


