def encode_rail_fence(s: str, n: int):
    """
    Takes a string s and n (odd integer) and returns the string encoded with rail-fence cipher
    with n rails.
    """
    # S = 49205492013120134041
    i = 0
    rail = [[] for _ in range(n)]
    while i < len(s):
        rail[i].append(s[i])
        i += 1
        if i == n:
            for j in range(n - 1, 0, -1):
                rail[j].append(s[i])
                i += 1
                if i == len(s):
                    break
    return "".join([item for rail in rail for item in rail])


def decode_rail_fence(s: str, n: int):
    """
    Takes a string s and n (odd integer) and returns the string decoded with rail-fence cipher
    with n rails.
    """
    rail = [[] for _ in range(n)]
    i = 0
    while i < len(s):
        rail[i].append(s[i])
        i += 1
        if i == n:
            for j in range(n - 1, 0, -1):
                rail[j].append(s[i])
                i += 1
                if i == len(s):
                    break
    rails_index = [i for i in range(n) for _ in range(len(rail[i]))]
    return "".join([s[j] for j in rails_index])


