def encrypt_vigenere(key: str, plaintext: str) -> str:
    """
    takes as input plaintext message and key. Returns encrypted message.
    """
    ciphertext = ""
    key_length = len(key)
    key_index = 0
    for plaintext_char in plaintext:
        if plaintext_char.isalpha():
            shift = ord(key[key_index % key_length]) - ord("a")
            ciphertext += chr(((ord(plaintext_char) + shift) % 26) + ord("a"))
            key_index += 1
        else:
            ciphertext += plaintext_char
    return ciphertext


def decrypt_vigenere(key: str, ciphertext: str) -> str:
    """
    takes as input ciphertext message and key. Returns decrypted message.
    """
    plaintext = ""
    key_length = len(key)
    key_index = 0
    for ciphertext_char in ciphertext:
        if ciphertext_char.isalpha():
            shift = ord(key[key_index % key_length]) - ord("a")
            plaintext += chr(((ord(ciphertext_char) - shift) % 26) + ord("a"))
            key_index += 1
        else:
            plaintext += ciphertext_char
    return plaintext


