def compute_probability(ori: str, char: str, res: str) -> float:
    """
    computes the probability of character occurence in original string.
    """
    n = len(ori)
    return (ori.count(char) + 1) / (n + len(gen_pol(res)))


def compute_distance(ori: str, res: str) -> float:
    """
    returns minimum edit distance between original string and result of encode_shift function
    """
    m = len(ori)
    n = len(res)

    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif ori[i - 1] == res[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j - 1], dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]


