def strange_sort_dict(dict_):
    '''
    Given dictionary of integers, return dictionary in strange order.
    Strange sorting, is when you start with the minimum value,
    then maximum of the remaining integers, then minimum and so on.

    Examples:
    strange_sort_dict({1: 1, 2: 2, 3: 3, 4: 4}) == {1: 1, 4: 4, 2: 2, 3: 3}
    strange_sort_dict({1: 1, 2: 2, 3: 3, 4: 4}) == {1: 1, 4: 4, 2: 2, 3: 3}
    strange_sort_dict({}) == {}
    '''
    if dict_:
        dict_ = sorted(dict_.items(), key=lambda x: x[1])
        dict_.sort(key=lambda x: -x[1])
        return {dict_[0][0]: dict_[0][1]} + strange_sort_dict(dict_[1:])
    else:
        return {}


