def bits_of_n(n):
    """
    How many bit must be switched if the bits of n are to be flipped.
    For example, if n = 3, then it is 2^2, as n = 101 in binary and one switch is
    needed to get 010, and another to get 100, making a total of 2 switches.
    """
    n_b = bin(n)[2:]
    n_bs = n_b.count('1')
    if n_bs % 2 == 0:
        return n_bs // 2
    else:
        return (n_bs // 2) + 1


def end_with_1(n):
    """
    Count of n-digit integers that end with 1.
